import{_ as l,o,c as r,ah as n}from"./chunks/framework.DjU4PSOm.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"문제의식","slug":"문제의식","link":"#문제의식","children":[]},{"level":2,"title":"친사(親士)와 상현(尙賢)","slug":"친사-親士-와-상현-尙賢","link":"#친사-親士-와-상현-尙賢","children":[]},{"level":2,"title":"겸애(兼愛)","slug":"겸애-兼愛","link":"#겸애-兼愛","children":[]},{"level":2,"title":"비명(非命) — 숙명론 비판","slug":"비명-非命-—-숙명론-비판","link":"#비명-非命-—-숙명론-비판","children":[]},{"level":2,"title":"묵가의 사상에 대한 평가 (비판적 검토)","slug":"묵가의-사상에-대한-평가-비판적-검토","link":"#묵가의-사상에-대한-평가-비판적-검토","children":[]}],"relativePath":"philosophy/China/03. 묵자.md","filePath":"philosophy/China/03. 묵자.md"}'),i={name:"philosophy/China/03. 묵자.md"};function e(s,t,a,g,h,p){return o(),r("div",null,[...t[0]||(t[0]=[n('<h2 id="문제의식" tabindex="-1">문제의식 <a class="header-anchor" href="#문제의식" aria-label="Permalink to &quot;문제의식&quot;">​</a></h2><p>어떤 것이 실제로 시민과 국가에 이로운가?</p><ol><li><strong>왜 살기 힘든가?</strong> → 전쟁 때문. 모든 침략전쟁을 반대 — 전쟁이 사라져야 백성이 생산활동에 종사할 수 있음</li><li><strong>전쟁은 왜 발생하는가?</strong> → 서로 사랑하지 않아서(<strong>별애</strong>). 별애에서 <strong>겸애</strong>로 전환해야 함</li><li><strong>국가를 어떤 기준으로 운영할 것인가?</strong> → 혈연 중심이 아닌, 누가 공동체의 이익을 증진시킬 수 있는가로</li><li><strong>공동체의 이익을 증진하려면?</strong> → 노동자의 휴식, 생산과 소비를 핵심으로 다뤄야 함 (절용, 절장, 비악 등)</li></ol><h2 id="친사-親士-와-상현-尙賢" tabindex="-1">친사(親士)와 상현(尙賢) <a class="header-anchor" href="#친사-親士-와-상현-尙賢" aria-label="Permalink to &quot;친사(親士)와 상현(尙賢)&quot;">​</a></h2><p>선비를 소중하게 생각해야 함 — 국가를 잘 운영하려면 현자를 숭상하고 능력 있는 사람을 등용해야 함. 등용한 뒤에는 반드시 높은 대우를 해줘야 함(현자를 위해서가 아니라 공동체의 이익을 위해서).</p><ul><li>반세습적 성격이 강함</li><li>능력주의적 요소가 강함</li><li>현실 행정론을 포함</li><li>관료의 공공성을 강조</li></ul><p><strong>묵자의 도덕성 기준</strong>: 공동체의 이익 — 유가는 묵가를 향해 &quot;실질적으로 이익이 없는 도덕은 공허하다&quot;고 비판.</p><h2 id="겸애-兼愛" tabindex="-1">겸애(兼愛) <a class="header-anchor" href="#겸애-兼愛" aria-label="Permalink to &quot;겸애(兼愛)&quot;">​</a></h2><p><strong>법의(法儀)</strong>: 천하의 백성을 동등하게 사랑해야 함.</p><p><strong>겸애의 논리</strong>: 혼란의 원인은 <strong>별애</strong>(차별적 사랑)에 있음 — 서로 사랑하지 않기 때문. <strong>겸상애(兼相愛)</strong> — 남 사랑하기를 자기 몸 사랑하듯 하라. <strong>겸상애 교상리(兼相愛 交相利)</strong> — 서로 사랑하고 서로 이롭게 하는 것.</p><p><strong>설득의 논리</strong>: 군주가 그것을 좋아하면 사람들이 그것을 행함. 별애를 주장하는 사람과 겸애를 주장하는 사람 중 누구에게 내 부모를 맡기겠는가? — 별애를 주장하는 사람조차도 자신에게 일이 닥치면 겸애를 주장하는 사람에게 맡김.</p><p><strong>평화주의자인가?</strong>: 침략전쟁은 비판하지만, 잘못된 국가를 바로잡기 위한 정벌이나 방어전쟁은 허용 — 오히려 전쟁 억제가 목적. 의로움이 이유가 아니라, 전쟁이 공동체의 이익에 해를 끼치기 때문. 겸상애 교상리는 <strong>하늘의 뜻</strong>이라고 주장.</p><h2 id="비명-非命-—-숙명론-비판" tabindex="-1">비명(非命) — 숙명론 비판 <a class="header-anchor" href="#비명-非命-—-숙명론-비판" aria-label="Permalink to &quot;비명(非命) — 숙명론 비판&quot;">​</a></h2><p>숙명론(&quot;성실하게 살면 하늘이 복을 내리고 그렇지 않으면 벌을 내린다&quot;는 통속적 이해와 달리, 운명이 이미 정해져 있다는 주장)을 비판.</p><ol><li><strong>인간의 노력을 무력화</strong>: 부유함·가난이 모두 운명이라면 애써도 소용없다는 생각을 갖게 되어, 통치자는 정치를 바로 하려는 의지를, 백성은 생업에 힘쓸 이유를 잃음</li><li><strong>지배층의 무책임을 정당화</strong>: 국가의 문제를 모두 운명으로 돌리면 통치자가 자신의 잘못을 알지 못함</li><li><strong>하늘의 뜻에 대한 올바른 이해를 막음</strong>: 하늘은 단순한 자연 질서가 아니라, 상벌을 행하고 백성을 사랑하는 도덕적 주재자</li></ol><h2 id="묵가의-사상에-대한-평가-비판적-검토" tabindex="-1">묵가의 사상에 대한 평가 (비판적 검토) <a class="header-anchor" href="#묵가의-사상에-대한-평가-비판적-검토" aria-label="Permalink to &quot;묵가의 사상에 대한 평가 (비판적 검토)&quot;">​</a></h2><ol><li><strong>다원적 판단은 혼란을 낳는다는 전제가 타당한가?</strong>: 의견의 차이가 곧바로 사회적 혼란을 야기하는지는 의문</li><li><strong>규범 통일이 강해질수록 기준을 정하는 자의 권력이 과도해지지 않는가?</strong>: 결국 인간이 하늘의 뜻을 해석해야 하므로, 해석하는 상층 권력에 집중되는 구조를 띔</li><li><strong>공익 실현이라는 문제의식은 타당하나, 그 실현 방식으로 규범의 강한 통일을 요구한 것은 과도함</strong>: 공익의 필요는 잘 짚었지만, 그것을 다원성의 억제와 거의 동일시함 — 오히려 최소한의 공유 규범 + 해석과 실천의 다원성이 필요</li></ol>',17)])])}const u=l(i,[["render",e]]);export{c as __pageData,u as default};
